-- Original Year 9 lesson activities and topic coverage. Rerunning updates the named original lessons and skips existing additions.
DO $year9$
DECLARE
 payload jsonb := $json${"existing": [{"title": "Rational and Irrational Numbers", "flow": {"recall": {"prompt": "Write 0.125 as a fraction.", "solution": "0.125=125/1000=1/8, so it is rational."}, "guided": {"prompt": "Is √20 rational or irrational? Explain.", "solution": "It is irrational because 20 is not a perfect square; √20=2√5."}, "application": {"prompt": "A circular garden has diameter 10 m. Give its exact perimeter and an estimate.", "solution": "C=10π m exactly, about 31.4 m."}, "review": {"prompt": "Classify √16 and √17.", "solution": "√16=4 is rational; √17 is irrational."}}}, {"title": "Index Laws and Scientific Notation", "flow": {"recall": {"prompt": "What does 2³ mean?", "solution": "2×2×2=8."}, "guided": {"prompt": "Simplify x⁷÷x⁹ with a positive exponent.", "solution": "x⁻²=1/x² for x≠0."}, "application": {"prompt": "Write 0.0000062 in scientific notation.", "solution": "6.2×10⁻⁶."}, "review": {"prompt": "Convert 4.1×10⁵ to ordinary notation.", "solution": "410,000."}}}, {"title": "Expanding and Factorising", "flow": {"recall": {"prompt": "Expand 3(x+2).", "solution": "3x+6."}, "guided": {"prompt": "Factorise x²+7x+12.", "solution": "Find 3 and 4: (x+3)(x+4)."}, "application": {"prompt": "A rectangle has sides x+3 and x+4. Write its area two ways.", "solution": "(x+3)(x+4)=x²+7x+12 square units."}, "review": {"prompt": "Check (x+3)(x+4) by expanding.", "solution": "x²+4x+3x+12=x²+7x+12."}}}, {"title": "Gradient and the Equation of a Line", "flow": {"recall": {"prompt": "In y=4x+1, what is the gradient?", "solution": "The gradient is 4."}, "guided": {"prompt": "Find the gradient between (1,2) and (3,8).", "solution": "(8−2)/(3−1)=3."}, "application": {"prompt": "A line has gradient 2 and passes through (0,5). Find the rule and y at x=4.", "solution": "y=2x+5; y(4)=13."}, "review": {"prompt": "What does a negative gradient tell you?", "solution": "y decreases as x increases."}}}, {"title": "Parabolas, Roots and Factorisation", "flow": {"recall": {"prompt": "Solve x−4=0.", "solution": "x=4."}, "guided": {"prompt": "Find the roots of (x+2)(x−5)=0.", "solution": "x=−2 or 5."}, "application": {"prompt": "A quadratic is zero at x=−1 and x=3. Write a possible monic rule.", "solution": "y=(x+1)(x−3)."}, "review": {"prompt": "Where does y=(x−2)(x+4) cross the x-axis?", "solution": "At x=2 and x=−4."}}}, {"title": "Direct Proportion and Simple Interest", "flow": {"recall": {"prompt": "Calculate 10% of $200.", "solution": "$20."}, "guided": {"prompt": "If y=5x, find y when x=7.", "solution": "y=35; the constant of proportion is 5."}, "application": {"prompt": "A $300 loan at 8% simple annual interest lasts 2 years. Calculate interest.", "solution": "I=300×0.08×2=$48."}, "review": {"prompt": "Why is y=5x+2 not direct proportion?", "solution": "At x=0, y=2, so it does not pass through the origin."}}}, {"title": "Surface Area, Volume and Percentage Error", "flow": {"recall": {"prompt": "What units describe volume?", "solution": "Cubic units, such as cm³."}, "guided": {"prompt": "Find volume for radius 2 cm and height 3 cm.", "solution": "π×2²×3=12π cm³."}, "application": {"prompt": "An estimate is 102 cm³ and actual volume 100 cm³. Find percentage error.", "solution": "|102−100|/100×100%=2%."}, "review": {"prompt": "Why does cylinder volume involve r²?", "solution": "The circular cross-section has area πr²."}}}, {"title": "Right-Triangle Lengths and Angles", "flow": {"recall": {"prompt": "Identify the hypotenuse.", "solution": "It is opposite the right angle and is the longest side."}, "guided": {"prompt": "Find the hypotenuse of legs 8 and 15.", "solution": "√(8²+15²)=√289=17."}, "application": {"prompt": "A 10 m ramp rises 6 m. Find its horizontal run.", "solution": "√(10²−6²)=8 m."}, "review": {"prompt": "Which trig ratio relates opposite and hypotenuse?", "solution": "Sine."}}}, {"title": "Scale Factors and Similar Shapes", "flow": {"recall": {"prompt": "Double a 3 cm side.", "solution": "The new side is 6 cm."}, "guided": {"prompt": "A side 6 cm enlarges to 15 cm. Find the factor.", "solution": "15/6=2.5."}, "application": {"prompt": "If a shape’s sides triple, what happens to area?", "solution": "Area multiplies by 3²=9."}, "review": {"prompt": "Can similar shapes have different areas?", "solution": "Yes; side lengths can differ by a common factor."}}}, {"title": "Mean, Median and Spread", "flow": {"recall": {"prompt": "Find the median of 1,5,7.", "solution": "5 is the middle value."}, "guided": {"prompt": "Find the range of 3,5,8,11.", "solution": "11−3=8."}, "application": {"prompt": "Scores 2,3,4,5,26 include an extreme value. Which centre better represents a typical score?", "solution": "Median 4 is more resistant than the mean 8."}, "review": {"prompt": "Why sort the data before finding median?", "solution": "The median is determined by the middle position."}}}, {"title": "Two-Step Events and Tree Diagrams", "flow": {"recall": {"prompt": "What is P(heads) for a fair coin?", "solution": "1/2."}, "guided": {"prompt": "A coin is tossed twice. Find P(heads then tails).", "solution": "(1/2)(1/2)=1/4."}, "application": {"prompt": "Draw two counters without replacement from 3 red and 2 blue. Find P(two blue).", "solution": "(2/5)(1/4)=1/10."}, "review": {"prompt": "When do you add branches of a tree?", "solution": "When distinct sequences each satisfy an either/or event."}}}], "added": [{"module": "Real Numbers and Indices", "title": "Square Roots and Surds", "objective": "Recognise exact square-root values and simplify basic surds.", "notes": "A square root asks which non-negative number squares to the given value. If a number is not a perfect square, leave the root exact when possible. To simplify √(ab), split off a perfect-square factor: √(9×2)=3√2. Estimate between neighbouring square numbers to check reasonableness.", "worked_example": "√72=√(36×2)=6√2. Since 8²=64 and 9²=81, √72 lies between 8 and 9.", "flow": {"recall": {"prompt": "What is 8²?", "solution": "64."}, "guided": {"prompt": "Simplify √50 by finding its largest square factor.", "solution": "√50=√(25×2)=5√2."}, "application": {"prompt": "A square tile has area 18 cm². Give the exact side length and an approximate value.", "solution": "Its side is √18=3√2 cm, about 4.24 cm."}, "review": {"prompt": "Without looking above, state the key rule and one situation where you would use it.", "solution": "For square roots and surds, check your explanation against the key ideas and worked example above."}}, "questions": [{"prompt": "√48 simplifies to…", "options": ["4√3", "8√3", "12√2", "24"], "correct_index": 0, "explanation": "48=16×3, so √48=4√3."}]}, {"module": "Real Numbers and Indices", "title": "Zero and Negative Indices", "objective": "Interpret zero and negative powers as reciprocals.", "notes": "For a non-zero base, a⁰=1 and a⁻ⁿ=1/aⁿ. A negative exponent does not make the value negative. Use index laws first, then rewrite with positive exponents. Zero cannot be a denominator.", "worked_example": "2³÷2⁵=2⁻²=1/4. Also (3x)⁰=1 provided x≠0.", "flow": {"recall": {"prompt": "What is 4²?", "solution": "16."}, "guided": {"prompt": "Write 5⁻³ as a fraction.", "solution": "5⁻³=1/5³=1/125."}, "application": {"prompt": "A machine reduces a measurement by a factor of 10 each stage. What fraction remains after four stages?", "solution": "(1/10)⁴=10⁻⁴=1/10,000."}, "review": {"prompt": "Without looking above, state the key rule and one situation where you would use it.", "solution": "For zero and negative indices, check your explanation against the key ideas and worked example above."}}, "questions": [{"prompt": "What is 4⁻²?", "options": ["1/16", "−16", "−8", "16"], "correct_index": 0, "explanation": "A negative index gives a reciprocal: 4⁻²=1/4²=1/16."}]}, {"module": "Algebraic Expressions", "title": "Expanding Binomials", "objective": "Multiply every term in one bracket by every term in the other.", "notes": "The distributive law applies twice when two binomials multiply. Combine like terms only after producing all four products. Check by substituting a simple value for x into both original and expanded forms.", "worked_example": "(x+3)(x−2)=x²−2x+3x−6=x²+x−6.", "flow": {"recall": {"prompt": "Expand 2(x+3).", "solution": "2x+6."}, "guided": {"prompt": "Expand (x−4)(x+2).", "solution": "x²+2x−4x−8=x²−2x−8."}, "application": {"prompt": "A rectangle has sides x+2 and x+5 metres. Express its area in expanded form.", "solution": "Area=(x+2)(x+5)=x²+7x+10 m²."}, "review": {"prompt": "Without looking above, state the key rule and one situation where you would use it.", "solution": "For expanding binomials, check your explanation against the key ideas and worked example above."}}, "questions": [{"prompt": "Expand (x+1)(x+7).", "options": ["x²+8x+7", "x²+7x+8", "x²+8x+8", "2x²+8x+7"], "correct_index": 0, "explanation": "The products give x²+7x+x+7=x²+8x+7."}]}, {"module": "Algebraic Expressions", "title": "Difference of Squares", "objective": "Recognise and factorise expressions of the form a²−b².", "notes": "A difference of two squares has two square terms separated by subtraction. It factors as (a−b)(a+b). The middle terms cancel when expanded. A sum of squares does not use this pattern over the real numbers.", "worked_example": "x²−25=x²−5²=(x−5)(x+5).", "flow": {"recall": {"prompt": "What is 7²?", "solution": "49."}, "guided": {"prompt": "Factorise 9x²−16.", "solution": "(3x)²−4²=(3x−4)(3x+4)."}, "application": {"prompt": "A large square has side x metres and a smaller cut-out has side 3 metres. Factorise the remaining area.", "solution": "The remaining area is x²−9=(x−3)(x+3) m²."}, "review": {"prompt": "Without looking above, state the key rule and one situation where you would use it.", "solution": "For difference of squares, check your explanation against the key ideas and worked example above."}}, "questions": [{"prompt": "Factorise x²−49.", "options": ["(x−7)(x+7)", "(x−49)(x+1)", "(x−7)²", "(x+7)²"], "correct_index": 0, "explanation": "x²−49=x²−7²=(x−7)(x+7)."}]}, {"module": "Algebraic Expressions", "title": "Algebraic Fractions", "objective": "Simplify fractions by cancelling common factors, with restrictions.", "notes": "Factorise numerator and denominator before cancelling. You may cancel a factor, not a term within a sum. Any x-value that makes the original denominator zero remains excluded even if the factor cancels.", "worked_example": "(x²−9)/(x−3)=(x−3)(x+3)/(x−3)=x+3, provided x≠3.", "flow": {"recall": {"prompt": "Factorise x²−9.", "solution": "(x−3)(x+3)."}, "guided": {"prompt": "Simplify (x²−4)/(x+2) and state the restriction.", "solution": "(x−2)(x+2)/(x+2)=x−2, with x≠−2."}, "application": {"prompt": "A formula for a quantity is (t²−16)/(t−4). What is the simplified form when t=5?", "solution": "It simplifies to t+4 for t≠4; at t=5 the value is 9."}, "review": {"prompt": "Without looking above, state the key rule and one situation where you would use it.", "solution": "For algebraic fractions, check your explanation against the key ideas and worked example above."}}, "questions": [{"prompt": "Simplify (x²−1)/(x−1), x≠1.", "options": ["x+1", "x−1", "1", "x²+1"], "correct_index": 0, "explanation": "(x²−1)/(x−1)=(x−1)(x+1)/(x−1)=x+1 when x≠1."}]}, {"module": "Linear Equations and Graphs", "title": "Solving Equations and Inequalities", "objective": "Solve linear statements while preserving equality or inequality.", "notes": "Undo operations in reverse order, doing the same thing to both sides. For inequalities, reverse the direction when multiplying or dividing by a negative number. Substitute a test value to check whether an inequality solution makes sense.", "worked_example": "3x+5=20 gives x=5. For −2x<6, division by −2 reverses the sign: x>−3.", "flow": {"recall": {"prompt": "Solve 2x=10.", "solution": "x=5."}, "guided": {"prompt": "Solve 4x−7=17.", "solution": "Add 7 to get 4x=24; divide by 4, so x=6."}, "application": {"prompt": "A ride costs $4 entry plus $3 per game. You have at most $19. How many whole games can you play?", "solution": "4+3g≤19 gives g≤5, so at most five games."}, "review": {"prompt": "Without looking above, state the key rule and one situation where you would use it.", "solution": "For solving equations and inequalities, check your explanation against the key ideas and worked example above."}}, "questions": [{"prompt": "Solve −3x>12.", "options": ["x<−4", "x>−4", "x<4", "x>4"], "correct_index": 0, "explanation": "Divide by −3 and reverse the inequality: x<−4."}]}, {"module": "Linear Equations and Graphs", "title": "Simultaneous Equations", "objective": "Find a pair of values that satisfies two linear equations.", "notes": "A solution to simultaneous equations is an intersection: it must satisfy both rules. Substitution replaces one variable with an expression from the other equation. Elimination adds or subtracts equations to remove a variable. Check your pair in both original equations.", "worked_example": "Solve x+y=10 and x−y=2. Add equations: 2x=12, so x=6 and y=4.", "flow": {"recall": {"prompt": "Solve x+y=8 for y.", "solution": "y=8−x."}, "guided": {"prompt": "Solve x+y=8 and x−y=4.", "solution": "Adding yields 2x=12, x=6; then y=2."}, "application": {"prompt": "Two items cost $10 together; the first costs $2 more. What are their prices?", "solution": "x+y=10 and x−y=2 gives $6 and $4."}, "review": {"prompt": "Without looking above, state the key rule and one situation where you would use it.", "solution": "For simultaneous equations, check your explanation against the key ideas and worked example above."}}, "questions": [{"prompt": "Which pair solves x+y=7 and x−y=1?", "options": ["(4,3)", "(3,4)", "(5,2)", "(7,1)"], "correct_index": 0, "explanation": "4+3=7 and 4−3=1, so the pair is (4,3)."}]}, {"module": "Linear Equations and Graphs", "title": "Linear Modelling", "objective": "Interpret a gradient and intercept in a real situation.", "notes": "For y=mx+c, the intercept c is the starting amount when x=0; m is change in y per one x-unit. Include units and check whether a model is sensible outside the measured range. A straight graph is directly proportional only if c=0.", "worked_example": "A tank begins with 80 L and fills at 12 L/min: V=80+12t. At t=5, V=140 L.", "flow": {"recall": {"prompt": "In y=3x+2, identify the intercept.", "solution": "2."}, "guided": {"prompt": "A phone balance begins at $40 and falls $3 per day. Write the rule.", "solution": "B=40−3d, where d is days and B is dollars."}, "application": {"prompt": "A parking fee is $6 entry plus $2 per hour. Identify the intercept and gradient and predict 3 hours.", "solution": "Intercept $6, gradient $2/hour; C=6+2h and C(3)=$12."}, "review": {"prompt": "Without looking above, state the key rule and one situation where you would use it.", "solution": "For linear modelling, check your explanation against the key ideas and worked example above."}}, "questions": [{"prompt": "In C=12+5h, what does 5 mean?", "options": ["$5 per hour", "$5 starting fee", "5 hours free", "$5 total"], "correct_index": 0, "explanation": "The coefficient of h is the change in cost for each additional hour."}]}, {"module": "Quadratic Equations and Graphs", "title": "Features of a Parabola", "objective": "Identify turning point, symmetry and intercepts from a quadratic rule.", "notes": "A quadratic y=ax²+bx+c graphs as a parabola. If a>0 it opens upwards; if a<0 it opens downwards. For vertex form y=a(x−h)²+k, the turning point is (h,k) and the axis of symmetry is x=h. The y-intercept occurs at x=0.", "worked_example": "y=(x−2)²+1 has a minimum of 1 at x=2 and axis x=2. At x=0, y=5.", "flow": {"recall": {"prompt": "What happens at an x-intercept?", "solution": "y=0."}, "guided": {"prompt": "State the vertex and direction of y=−(x+1)²+4.", "solution": "Vertex (−1,4); negative coefficient means it opens down."}, "application": {"prompt": "The height of a ball is h=−(t−3)²+9. When does it reach maximum height, and what is it?", "solution": "The turning point is (3,9), so after 3 seconds it reaches 9 metres."}, "review": {"prompt": "Without looking above, state the key rule and one situation where you would use it.", "solution": "For features of a parabola, check your explanation against the key ideas and worked example above."}}, "questions": [{"prompt": "What is the vertex of y=(x−4)²−2?", "options": ["(4,−2)", "(−4,−2)", "(4,2)", "(−4,2)"], "correct_index": 0, "explanation": "In vertex form y=(x−h)²+k, the vertex is (h,k)."}]}, {"module": "Quadratic Equations and Graphs", "title": "Solving Quadratics by Factorisation", "objective": "Use the null factor law after writing a quadratic equal to zero.", "notes": "First put all terms on one side. Factorise, then set each factor equal to zero. If a product is zero, at least one factor must be zero. Check each answer in the original equation. Not every quadratic factors neatly, so this method has limits.", "worked_example": "x²+2x−15=0 becomes (x+5)(x−3)=0, giving x=−5 or 3.", "flow": {"recall": {"prompt": "Factorise x²−9.", "solution": "(x−3)(x+3)."}, "guided": {"prompt": "Solve x²−5x+6=0.", "solution": "(x−2)(x−3)=0, so x=2 or 3."}, "application": {"prompt": "A rectangle has sides x and x+2, and area 48 cm². Find the positive value of x.", "solution": "x(x+2)=48, so x²+2x−48=(x+8)(x−6)=0. Length x=6 cm."}, "review": {"prompt": "Without looking above, state the key rule and one situation where you would use it.", "solution": "For solving quadratics by factorisation, check your explanation against the key ideas and worked example above."}}, "questions": [{"prompt": "Solve x²−9=0.", "options": ["x=−3 or 3", "x=3 only", "x=9", "x=−9 or 9"], "correct_index": 0, "explanation": "x²−9=(x−3)(x+3), so x=3 or −3."}]}, {"module": "Rates, Proportion and Financial Maths", "title": "Ratios, Rates and Best Buys", "objective": "Compare quantities using common units and unit prices.", "notes": "A ratio compares like quantities; a rate compares different units, such as dollars per kilogram. To compare packs, find the same unit price. Convert units before dividing and explain whether a lower unit price is actually the best choice for the buyer.", "worked_example": "A 750 g pack costs $6.00: $6/0.75 kg=$8/kg. A 1 kg pack at $7.50 has lower unit price.", "flow": {"recall": {"prompt": "How many grams are in a kilogram?", "solution": "1000 g."}, "guided": {"prompt": "A 400 g pack costs $3.20. Find its cost per kilogram.", "solution": "$3.20/0.4 kg=$8/kg."}, "application": {"prompt": "Pack A is 600 g for $4.80 and B is 1 kg for $7.50. Which has lower unit price?", "solution": "A is $8/kg; B is $7.50/kg, so B."}, "review": {"prompt": "Without looking above, state the key rule and one situation where you would use it.", "solution": "For ratios, rates and best buys, check your explanation against the key ideas and worked example above."}}, "questions": [{"prompt": "Which is cheaper per litre: 2 L for $5 or 3 L for $6?", "options": ["3 L for $6", "2 L for $5", "Same price", "Cannot compare"], "correct_index": 0, "explanation": "$5/2=$2.50/L; $6/3=$2/L, so the 3 L option is cheaper per litre."}]}, {"module": "Rates, Proportion and Financial Maths", "title": "Percentage Change and Discounts", "objective": "Calculate changes relative to the original amount.", "notes": "A percentage change is change/original ×100%. To apply a discount of p%, multiply the original by 1−p/100. Consecutive percentage changes act on different bases; a 10% rise followed by a 10% fall does not return to the original amount.", "worked_example": "An $80 item discounted by 25% costs 80×0.75=$60.", "flow": {"recall": {"prompt": "Find 10% of $50.", "solution": "$5."}, "guided": {"prompt": "A price rises from $40 to $50. Find the percentage increase.", "solution": "Change $10 divided by original $40 gives 25%."}, "application": {"prompt": "A $100 item rises by 20%, then is discounted by 20%. Find the final price.", "solution": "$100×1.2×0.8=$96; the percentage changes do not cancel."}, "review": {"prompt": "Without looking above, state the key rule and one situation where you would use it.", "solution": "For percentage change and discounts, check your explanation against the key ideas and worked example above."}}, "questions": [{"prompt": "A $60 item discounted 15% costs…", "options": ["$51", "$45", "$54", "$69"], "correct_index": 0, "explanation": "15% of $60 is $9; $60−$9=$51."}]}, {"module": "Rates, Proportion and Financial Maths", "title": "Income, Tax and Compound Interest", "objective": "Distinguish gross pay, deductions and repeated interest.", "notes": "Gross pay is earnings before deductions; net pay is after deductions. For compound interest, each period earns interest on the updated balance: A=P(1+r)ⁿ, where r is the rate per period. This differs from simple interest, which only uses the starting principal. Do not use an outdated tax bracket without checking current rules.", "worked_example": "A $1,000 account at 5% compounded annually for two years is 1000×1.05²=$1,102.50.", "flow": {"recall": {"prompt": "Calculate 5% of $100.", "solution": "$5."}, "guided": {"prompt": "Find one year of 4% compound interest on $500.", "solution": "500×1.04=$520; interest earned is $20."}, "application": {"prompt": "A $200 account earns 10% each year for two years. Compare compound and simple balances.", "solution": "Compound: 200×1.1²=$242; simple: 200+200×0.1×2=$240."}, "review": {"prompt": "Without looking above, state the key rule and one situation where you would use it.", "solution": "For income, tax and compound interest, check your explanation against the key ideas and worked example above."}}, "questions": [{"prompt": "At 10% compound interest for two years, $100 becomes…", "options": ["$121", "$120", "$110", "$122"], "correct_index": 0, "explanation": "100×1.1²=$121 because the second 10% is applied to $110."}]}, {"module": "Measurement and Accuracy", "title": "Area and Composite Shapes", "objective": "Split composite regions into familiar shapes with correct units.", "notes": "Find the area of a composite region by dividing it into rectangles, triangles or circles, then adding or subtracting pieces. Draw a labelled sketch and use consistent length units. Area units are squared; a boundary length is a perimeter, not an area.", "worked_example": "A 6 m by 4 m rectangle with a 2 m by 1 m corner removed has area 24−2=22 m².", "flow": {"recall": {"prompt": "Find the area of a 3 cm by 4 cm rectangle.", "solution": "12 cm²."}, "guided": {"prompt": "A rectangle 8 cm by 5 cm has a 3 cm by 2 cm hole. Find its area.", "solution": "40−6=34 cm²."}, "application": {"prompt": "A room 5 m by 4 m includes a 2 m by 1 m alcove. How much flooring is needed?", "solution": "Add the two non-overlapping rectangles: 20+2=22 m²."}, "review": {"prompt": "Without looking above, state the key rule and one situation where you would use it.", "solution": "For area and composite shapes, check your explanation against the key ideas and worked example above."}}, "questions": [{"prompt": "Area of a triangle with base 10 cm and height 6 cm is…", "options": ["30 cm²", "60 cm²", "16 cm²", "30 cm"], "correct_index": 0, "explanation": "Triangle area is base×height/2=10×6/2=30 cm²."}]}, {"module": "Measurement and Accuracy", "title": "Surface Area of Prisms", "objective": "Add the areas of all exposed faces of a solid.", "notes": "A prism has matching ends joined by rectangular faces. Total surface area adds the areas of every external face; an open container omits its missing face. A labelled net can prevent missed or repeated faces. Use square units.", "worked_example": "A box 2×3×4 cm has area 2(2×3+2×4+3×4)=52 cm².", "flow": {"recall": {"prompt": "How many faces does a cube have?", "solution": "Six."}, "guided": {"prompt": "Find surface area of a 2×2×3 cm closed rectangular prism.", "solution": "2(4+6+6)=32 cm²."}, "application": {"prompt": "An open-top box is 2 m by 3 m by 1 m. Find material for its base and four sides.", "solution": "Base 6; sides 2×2+2×3=10; total 16 m²."}, "review": {"prompt": "Without looking above, state the key rule and one situation where you would use it.", "solution": "For surface area of prisms, check your explanation against the key ideas and worked example above."}}, "questions": [{"prompt": "Closed cube of edge 3 cm has surface area…", "options": ["54 cm²", "27 cm²", "18 cm²", "9 cm²"], "correct_index": 0, "explanation": "A closed cube has six square faces; each is 3²=9 cm², total 54 cm²."}]}, {"module": "Measurement and Accuracy", "title": "Volume and Unit Conversions", "objective": "Calculate prism and cylinder volume using consistent units.", "notes": "Volume measures space inside a three-dimensional solid. For a prism, volume is cross-sectional area times length; a cylinder has volume πr²h. Convert all lengths to the same unit before multiplying. One cubic centimetre is one millilitre.", "worked_example": "A cylinder with radius 2 cm and height 5 cm has volume 20π cm³, about 62.8 mL.", "flow": {"recall": {"prompt": "Find the area of a 2 cm by 3 cm base.", "solution": "6 cm²."}, "guided": {"prompt": "Find volume of a 3×4×5 cm rectangular prism.", "solution": "3×4×5=60 cm³=60 mL."}, "application": {"prompt": "A tank is 1 m by 0.5 m by 0.4 m. How many litres can it hold?", "solution": "0.2 m³. Since 1 m³=1000 L, capacity is 200 L."}, "review": {"prompt": "Without looking above, state the key rule and one situation where you would use it.", "solution": "For volume and unit conversions, check your explanation against the key ideas and worked example above."}}, "questions": [{"prompt": "A 4×3×2 cm prism has volume…", "options": ["24 cm³", "9 cm³", "24 cm²", "12 cm³"], "correct_index": 0, "explanation": "Volume is 4×3×2=24 cubic centimetres."}]}, {"module": "Pythagoras and Trigonometry", "title": "Pythagoras and Distance", "objective": "Find unknown sides in right triangles and coordinate diagrams.", "notes": "For a right triangle, the square of the hypotenuse equals the sum of the squares of the shorter sides. Draw or identify the right angle first; c is always opposite it. Use the converse to check whether three side lengths form a right triangle.", "worked_example": "A 6 cm by 8 cm right triangle has hypotenuse √(36+64)=10 cm.", "flow": {"recall": {"prompt": "What is 3²+4²?", "solution": "25."}, "guided": {"prompt": "A right triangle has legs 5 and 12 cm. Find its hypotenuse.", "solution": "√(25+144)=13 cm."}, "application": {"prompt": "A ladder reaches 4 m up a wall and rests 3 m from it. How long is the ladder?", "solution": "The ladder is the hypotenuse: √(3²+4²)=5 m."}, "review": {"prompt": "Without looking above, state the key rule and one situation where you would use it.", "solution": "For pythagoras and distance, check your explanation against the key ideas and worked example above."}}, "questions": [{"prompt": "A right triangle with legs 9 and 12 has hypotenuse…", "options": ["15", "21", "√21", "18"], "correct_index": 0, "explanation": "√(9²+12²)=√225=15."}]}, {"module": "Pythagoras and Trigonometry", "title": "Using Trigonometric Ratios", "objective": "Select sine, cosine or tangent by identifying known sides.", "notes": "Relative to an acute angle, sine is opposite/hypotenuse, cosine is adjacent/hypotenuse, and tangent is opposite/adjacent. Label the triangle before choosing a ratio. Use degree mode for angle measurements stated in degrees; round only at the requested stage.", "worked_example": "If θ=30° and the hypotenuse is 10 cm, opposite=10 sin30°=5 cm.", "flow": {"recall": {"prompt": "Which side is opposite the right angle?", "solution": "The hypotenuse."}, "guided": {"prompt": "The side adjacent to a 60° angle has hypotenuse 8 cm. Find the adjacent side.", "solution": "8 cos60°=4 cm."}, "application": {"prompt": "A 5 m ramp rises at 20° above horizontal. Express its vertical rise and estimate it.", "solution": "Rise=5 sin20°≈1.71 m."}, "review": {"prompt": "Without looking above, state the key rule and one situation where you would use it.", "solution": "For using trigonometric ratios, check your explanation against the key ideas and worked example above."}}, "questions": [{"prompt": "Which ratio is opposite/adjacent?", "options": ["tangent", "sine", "cosine", "inverse cosine"], "correct_index": 0, "explanation": "Tangent compares the opposite and adjacent sides."}]}, {"module": "Similarity and Scale", "title": "Congruence and Similarity", "objective": "Tell equal-size congruent shapes from scaled similar shapes.", "notes": "Congruent figures have matching shape and size. Similar figures have matching corresponding angles and proportional corresponding sides, but can differ in size. Match vertices in order before forming ratios. An enlargement with factor 1 is congruent.", "worked_example": "Triangles with side sets (3,4,5) and (6,8,10) are similar with scale factor 2, but not congruent.", "flow": {"recall": {"prompt": "What does a scale factor of 2 do to length?", "solution": "It doubles length."}, "guided": {"prompt": "Triangles have corresponding sides 5,7 and 10,14. Find the scale factor.", "solution": "Each larger side is twice the smaller, so factor 2."}, "application": {"prompt": "A photo 6 cm wide is enlarged to 15 cm. What is the scale factor and the new height if it was 4 cm tall?", "solution": "Factor 15/6=2.5; new height 4×2.5=10 cm."}, "review": {"prompt": "Without looking above, state the key rule and one situation where you would use it.", "solution": "For congruence and similarity, check your explanation against the key ideas and worked example above."}}, "questions": [{"prompt": "Similar shapes always have…", "options": ["equal corresponding angles", "equal areas", "equal side lengths", "the same orientation"], "correct_index": 0, "explanation": "Similarity preserves angles while side lengths share a scale factor."}]}, {"module": "Similarity and Scale", "title": "Scale Drawings", "objective": "Convert between diagram distances and real distances.", "notes": "A scale such as 1:50 means one unit on the drawing represents fifty of the same units in reality. Multiply drawing lengths by the scale factor, or divide real lengths to find drawing lengths. Convert the answer to useful units. Area scales by the square of the length factor.", "worked_example": "At 1:100, a 3 cm line represents 300 cm=3 m.", "flow": {"recall": {"prompt": "Convert 3 m to centimetres.", "solution": "300 cm."}, "guided": {"prompt": "At 1:200, what does 4 cm represent?", "solution": "4×200=800 cm=8 m."}, "application": {"prompt": "A floor plan uses 1:50 and a wall is 6 m long. How long is the wall on the plan?", "solution": "6 m=600 cm; drawing=600/50=12 cm."}, "review": {"prompt": "Without looking above, state the key rule and one situation where you would use it.", "solution": "For scale drawings, check your explanation against the key ideas and worked example above."}}, "questions": [{"prompt": "At 1:100, 5 cm represents…", "options": ["5 m", "50 m", "0.5 m", "500 m"], "correct_index": 0, "explanation": "5×100=500 cm=5 m."}]}, {"module": "Similarity and Scale", "title": "Proving Similar Triangles", "objective": "Use corresponding angles and sides to justify similarity.", "notes": "Two triangles are similar if two pairs of corresponding angles are equal (AA), or all corresponding side lengths share one ratio (SSS). State which vertices correspond. Similarity then gives proportions for unknown lengths; it does not automatically mean congruence.", "worked_example": "If triangles have angles 40°,60°,80° each, they are similar by AA. If one side 4 maps to 10, the scale factor is 2.5.", "flow": {"recall": {"prompt": "What does similarity preserve?", "solution": "Corresponding angles and side ratios."}, "guided": {"prompt": "One triangle has angles 35° and 75°; another has 35° and 75°. Are they similar?", "solution": "Yes, by the angle-angle criterion; the third angles also match."}, "application": {"prompt": "Two triangles have corresponding sides 3 and 6, 4 and 8, 5 and 10. Explain similarity.", "solution": "Every larger side is twice the smaller: SSS similarity with factor 2."}, "review": {"prompt": "Without looking above, state the key rule and one situation where you would use it.", "solution": "For proving similar triangles, check your explanation against the key ideas and worked example above."}}, "questions": [{"prompt": "Which condition guarantees triangle similarity?", "options": ["Two corresponding angles equal", "One side equal", "Equal perimeters", "One angle equal"], "correct_index": 0, "explanation": "Two equal corresponding angles guarantee the third pair is equal too."}]}, {"module": "Statistics and Data", "title": "Choosing Displays and Samples", "objective": "Select a graph and recognise possible sampling bias.", "notes": "Categorical data suit bar charts; numerical data can use dot plots, histograms or stem-and-leaf displays. A sample should represent the population for the intended question. Convenience samples may leave out important groups. State what a graph shows, not just its highest bar.", "worked_example": "To estimate all students’ travel times, surveying only students arriving by bus gives a biased sample.", "flow": {"recall": {"prompt": "What is a categorical variable?", "solution": "A value representing a group or label."}, "guided": {"prompt": "Which graph suits counts of favourite subjects?", "solution": "A bar chart separates categories and compares their frequencies."}, "application": {"prompt": "A survey about school lunch only asks students in the canteen queue. What is the likely bias?", "solution": "Students who bring lunch may be missing, so the sample may not represent the school."}, "review": {"prompt": "Without looking above, state the key rule and one situation where you would use it.", "solution": "For choosing displays and samples, check your explanation against the key ideas and worked example above."}}, "questions": [{"prompt": "Best graph for counts of preferred sports?", "options": ["bar chart", "line of best fit", "scatterplot", "box plot"], "correct_index": 0, "explanation": "A bar chart compares frequencies across separate categories."}]}, {"module": "Statistics and Data", "title": "Measures of Centre and Spread", "objective": "Compare median, mean, range and interquartile range.", "notes": "Mean uses every value; median is the middle after sorting. Range is maximum−minimum. The interquartile range (IQR) is Q3−Q1 and describes the middle half of the data. An extreme value can shift the mean strongly, so median and IQR can be more informative for skewed data.", "worked_example": "For 2,3,4,5,16: mean=6, median=4, range=14. The high 16 raises the mean.", "flow": {"recall": {"prompt": "Find the median of 2,5,9.", "solution": "5."}, "guided": {"prompt": "Find mean and median of 1,2,3,4,10.", "solution": "Mean=20/5=4; median=3."}, "application": {"prompt": "Two groups have the same median but ranges of 4 and 20. Which is more spread out by range?", "solution": "The group with range 20. The common median does not imply similar variation."}, "review": {"prompt": "Without looking above, state the key rule and one situation where you would use it.", "solution": "For measures of centre and spread, check your explanation against the key ideas and worked example above."}}, "questions": [{"prompt": "Median of 2,4,9,11,20 is…", "options": ["9", "4", "11", "9.2"], "correct_index": 0, "explanation": "The middle of five ordered values is the third: 9."}]}, {"module": "Statistics and Data", "title": "Box Plots and Outliers", "objective": "Read a five-number summary and compare distributions.", "notes": "A box plot marks minimum, lower quartile, median, upper quartile and maximum. Its box length is IQR=Q3−Q1. Compare centre and spread; note asymmetry or possible outliers. A standard 1.5×IQR rule is one possible convention for flagging outliers, but always check the graph’s convention.", "worked_example": "For min 2, Q1 4, median 7, Q3 10, max 13, the IQR is 6.", "flow": {"recall": {"prompt": "What is the median?", "solution": "The middle ordered value."}, "guided": {"prompt": "Find IQR when Q1=12 and Q3=21.", "solution": "21−12=9."}, "application": {"prompt": "Class A has median 15 and IQR 4; B has median 15 and IQR 10. Compare typical score and middle-half spread.", "solution": "Same median; B has more spread in its middle half."}, "review": {"prompt": "Without looking above, state the key rule and one situation where you would use it.", "solution": "For box plots and outliers, check your explanation against the key ideas and worked example above."}}, "questions": [{"prompt": "If Q1=6 and Q3=14, IQR is…", "options": ["8", "20", "14", "6"], "correct_index": 0, "explanation": "IQR=Q3−Q1=14−6=8."}]}, {"module": "Probability", "title": "Venn Diagrams and Two-Way Tables", "objective": "Count unions and overlaps without double-counting.", "notes": "For two events A and B, P(A∪B)=P(A)+P(B)−P(A∩B). The overlap is counted in each individual event, so subtract it once. A two-way table organises joint categories; check row and column totals add to the same grand total.", "worked_example": "In a class of 30, 18 like maths, 14 like science and 8 like both. Number liking at least one=18+14−8=24.", "flow": {"recall": {"prompt": "What does an overlap mean in a Venn diagram?", "solution": "Members in both sets."}, "guided": {"prompt": "In 20 students, 12 like art, 9 music, 4 both. How many like at least one?", "solution": "12+9−4=17."}, "application": {"prompt": "Of 25 students, 10 play basketball, 12 volleyball and 5 both. How many play neither?", "solution": "Union=10+12−5=17; neither=25−17=8."}, "review": {"prompt": "Without looking above, state the key rule and one situation where you would use it.", "solution": "For venn diagrams and two-way tables, check your explanation against the key ideas and worked example above."}}, "questions": [{"prompt": "If |A|=12, |B|=9 and |A∩B|=4, |A∪B| is…", "options": ["17", "21", "25", "5"], "correct_index": 0, "explanation": "Union=12+9−4=17 because the overlap was counted twice."}]}, {"module": "Probability", "title": "Experimental and Theoretical Probability", "objective": "Compare a model with observed relative frequency.", "notes": "Theoretical probability describes an ideal model: favourable equally likely outcomes divided by all possible outcomes. Experimental probability is observed successes divided by trials. Small samples can differ substantially from the model; more trials often give a more stable estimate, but no exact outcome is guaranteed.", "worked_example": "A fair die has theoretical P(6)=1/6. If six appears 8 times in 30 rolls, experimental P(6)=8/30=4/15.", "flow": {"recall": {"prompt": "What is theoretical P(heads) for a fair coin?", "solution": "1/2."}, "guided": {"prompt": "A coin lands heads 18 times in 40 tosses. Find experimental probability.", "solution": "18/40=0.45, whereas the fair-coin theoretical value is 0.5."}, "application": {"prompt": "You need to estimate the chance of a machine producing a faulty item. Which probability source is most useful?", "solution": "Use many observed production outcomes because the machine’s true fault process is not a simple equally likely model."}, "review": {"prompt": "Without looking above, state the key rule and one situation where you would use it.", "solution": "For experimental and theoretical probability, check your explanation against the key ideas and worked example above."}}, "questions": [{"prompt": "7 successes in 20 trials gives experimental probability…", "options": ["0.35", "0.7", "0.07", "2.86"], "correct_index": 0, "explanation": "Observed fraction=7/20=0.35."}]}]}$json$::jsonb;
 item jsonb; v_course uuid := '3f85b4a0-e9bc-407e-bcbf-53d03ee354eb'; v_module uuid; v_lesson uuid; v_position integer; q jsonb;
BEGIN
 IF NOT EXISTS (SELECT 1 FROM public.courses WHERE id=v_course) THEN RAISE EXCEPTION 'Year 9 maths course missing'; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(payload->'existing') LOOP
   UPDATE public.lessons l SET lesson_flow=item->'flow' WHERE l.title=item->>'title' AND EXISTS (SELECT 1 FROM public.modules m WHERE m.id=l.module_id AND m.course_id=v_course) AND (l.lesson_flow IS NULL OR l.lesson_flow='{}'::jsonb);
 END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(payload->'added') LOOP
   SELECT id INTO v_module FROM public.modules WHERE course_id=v_course AND title=item->>'module' ORDER BY position LIMIT 1;
   IF v_module IS NULL THEN RAISE EXCEPTION 'Missing module: %',item->>'module'; END IF;
   SELECT id INTO v_lesson FROM public.lessons WHERE module_id=v_module AND title=item->>'title' LIMIT 1;
   IF v_lesson IS NULL THEN
     SELECT coalesce(max(position),-1)+1 INTO v_position FROM public.lessons WHERE module_id=v_module;
     INSERT INTO public.lessons(module_id,title,objective,notes,worked_example,lesson_flow,position) VALUES (v_module,item->>'title',item->>'objective',item->>'notes',item->>'worked_example',item->'flow',v_position) RETURNING id INTO v_lesson;
   END IF;
   FOR q IN SELECT value FROM jsonb_array_elements(item->'questions') LOOP
     IF NOT EXISTS(SELECT 1 FROM public.questions WHERE lesson_id=v_lesson AND prompt=q->>'prompt') THEN
       INSERT INTO public.questions(lesson_id,prompt,options,correct_index,explanation,position) VALUES(v_lesson,q->>'prompt',q->'options',(q->>'correct_index')::int,q->>'explanation',0);
     END IF;
   END LOOP;
 END LOOP;
END $year9$;
